head.b:skin:
/* ===== Base ===== */
html { -webkit-text-size-adjust: 100%; }
body {
    font-family: "Plus Jakarta Sans", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}
::selection { background: #4f46e5; color: #fff; }

/* ===== Legacy layout helpers ===== */
.section { width: 100%; }
.snip-row-12 { width: 100%; }
.post-title { margin-top: 0; }
.post-title a { color: inherit; text-decoration: none; }
.post-summary { overflow-wrap: anywhere; }

/* ===== Sidebar scrollbar ===== */
#side .wrapper::-webkit-scrollbar { width: 6px; }
#side .wrapper::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.18); border-radius: 999px; }
#side .wrapper::-webkit-scrollbar-track { background: transparent; }

/* ===== Post content typography ===== */
.post-content,
.post-body {
    color: #1e293b;
    font-size: 1.0625rem;
    line-height: 1.8;
    overflow-wrap: anywhere;
}
.post-content p,
.post-body p { margin: 0 0 1.1rem; }
.post-content h1, .post-body h1,
.post-content h2, .post-body h2,
.post-content h3, .post-body h3,
.post-content h4, .post-body h4 {
    color: #0f172a;
    font-weight: 800;
    line-height: 1.3;
    margin: 1.8rem 0 0.8rem;
}
.post-content h1, .post-body h1 { font-size: 1.9rem; }
.post-content h2, .post-body h2 { font-size: 1.55rem; }
.post-content h3, .post-body h3 { font-size: 1.25rem; }
.post-content h4, .post-body h4 { font-size: 1.05rem; }
.post-content a, .post-body a {
    color: #4f46e5;
    font-weight: 600;
    text-decoration: underline;
    text-decoration-thickness: 1.5px;
    text-underline-offset: 3px;
}
.post-content a:hover, .post-body a:hover { color: #4338ca; }
.post-content img, .post-body img {
    display: block;
    max-width: 100%;
    height: auto;
    margin: 1.25rem 0;
    border-radius: 1rem;
}
.post-content ul, .post-body ul { list-style: disc; margin: 0 0 1.1rem; padding-left: 1.5rem; }
.post-content ol, .post-body ol { list-style: decimal; margin: 0 0 1.1rem; padding-left: 1.5rem; }
.post-content li, .post-body li { margin-bottom: 0.4rem; }
.post-content blockquote, .post-body blockquote {
    margin: 1.4rem 0;
    padding: 0.9rem 1.2rem;
    background: #eef2ff;
    border-left: 4px solid #6366f1;
    border-radius: 0.75rem;
    color: #3730a3;
    font-style: italic;
}
.post-content pre, .post-body pre {
    margin: 1.4rem 0;
    padding: 1.1rem;
    background: #0f172a;
    color: #e2e8f0;
    border-radius: 1rem;
    overflow-x: auto;
    font-size: 0.875rem;
    line-height: 1.6;
}
.post-content code, .post-body code {
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size: 0.9em;
    background: #f1f5f9;
    color: #e11d48;
    padding: 0.15em 0.4em;
    border-radius: 0.35rem;
}
.post-content pre code, .post-body pre code {
    background: transparent;
    color: inherit;
    padding: 0;
}
.post-content table, .post-body table {
    display: block;
    width: 100%;
    margin: 1.4rem 0;
    border-collapse: collapse;
    overflow-x: auto;
}
.post-content table th, .post-content table td,
.post-body table th, .post-body table td {
    border: 1px solid #e2e8f0;
    padding: 0.6rem 0.8rem;
    text-align: left;
}
.post-content table th, .post-body table th { background: #f8fafc; font-weight: 700; }
.post-content hr, .post-body hr { border: 0; border-top: 1px solid #e2e8f0; margin: 2rem 0; }
.post-content figure, .post-body figure { margin: 1.4rem 0; }
.post-content iframe, .post-body iframe {
    max-width: 100%;
    border: 0;
    border-radius: 0.75rem;
}
.post-content .separator a { display: block; }
.post-content b, .post-content strong,
.post-body b, .post-body strong { color: #0f172a; font-weight: 700; }

/* ===== Archive card excerpt ===== */
.archive-excerpt .post-body {
    max-height: 9.5rem;
    overflow: hidden;
    font-size: 0.925rem;
    line-height: 1.7;
    -webkit-mask-image: linear-gradient(180deg, #000 55%, transparent 100%);
    mask-image: linear-gradient(180deg, #000 55%, transparent 100%);
}
.archive-excerpt a { color: inherit; pointer-events: none; text-decoration: none; }
.archive-excerpt img { border-radius: 0.75rem; }

/* ===== Pagination (paginationjs) ===== */
#pagination-container { display: flex; justify-content: center; }
#pagination-container .paginationjs {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    font-family: inherit;
    font-size: 14px;
    line-height: 1.4;
}
#pagination-container .paginationjs .paginationjs-pages { float: none; margin: 0; }
#pagination-container .paginationjs .paginationjs-pages ul {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    float: none;
    margin: 0;
    padding: 0;
}
#pagination-container .paginationjs .paginationjs-pages li {
    float: none;
    margin: 0;
    border: 0;
    border-radius: 0;
    list-style: none;
}
#pagination-container .paginationjs .paginationjs-pages li > a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2.5rem;
    height: 2.5rem;
    padding: 0 0.75rem;
    border: 1px solid #e2e8f0;
    border-radius: 0.85rem;
    background: #fff;
    color: #334155;
    font-size: 0.875rem;
    font-weight: 600;
    text-decoration: none;
    transition: all 0.15s ease;
}
#pagination-container .paginationjs .paginationjs-pages li > a:hover {
    border-color: #c7d2fe;
    background: #eef2ff;
    color: #4f46e5;
}
#pagination-container .paginationjs .paginationjs-pages li.active > a {
    border-color: #4f46e5;
    background: #4f46e5;
    color: #fff;
    box-shadow: 0 8px 18px -8px rgba(79, 70, 229, 0.7);
    cursor: default;
}
#pagination-container .paginationjs .paginationjs-pages li.disabled > a {
    opacity: 0.4;
    cursor: default;
    pointer-events: none;
}
#pagination-container .paginationjs .paginationjs-go-input,
#pagination-container .paginationjs .paginationjs-go-button,
#pagination-container .paginationjs .paginationjs-size-changer,
#pagination-container .paginationjs .paginationjs-nav {
    float: none;
    margin: 0;
    height: auto;
    line-height: 1;
}
#pagination-container .paginationjs .paginationjs-go-input > input[type=text] {
    width: 3.4rem;
    height: 2.5rem;
    border: 1px solid #e2e8f0;
    border-radius: 0.85rem;
    background: #fff;
    padding: 0 0.6rem;
    font-size: 0.875rem;
    text-align: center;
    outline: none;
    color: #0f172a;
}
#pagination-container .paginationjs .paginationjs-go-input > input[type=text]:focus {
    border-color: #a5b4fc;
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.15);
}
#pagination-container .paginationjs .paginationjs-go-button > input[type=button] {
    min-width: auto;
    height: 2.5rem;
    border: 0;
    border-radius: 0.85rem;
    background: #0f172a;
    color: #fff;
    padding: 0 1rem;
    font-size: 0.875rem;
    font-weight: 600;
    cursor: pointer;
}
#pagination-container .paginationjs .paginationjs-go-button > input[type=button]:hover { background: #4f46e5; }
#pagination-container .paginationjs .paginationjs-nav { font-size: 0.8rem; color: #64748b; }

/* ===== Comments ===== */
#comments { margin-top: 2rem; }
.comments .title,
#comment-post-message {
    margin: 0 0 1rem;
    color: #0f172a;
    font-size: 1.125rem;
    font-weight: 800;
}
.comment {
    display: flex;
    gap: 0.9rem;
    margin-bottom: 0.75rem;
    padding: 1rem;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
}
.avatar-image-container { flex-shrink: 0; }
.avatar-image-container img {
    width: 38px !important;
    height: 38px !important;
    border-radius: 999px;
    object-fit: cover;
}
.comment-block { flex: 1; min-width: 0; }
.comment-author { margin-bottom: 0.35rem; color: #0f172a; font-size: 0.85rem; font-weight: 700; }
.comment-body { color: #475569; font-size: 0.925rem; line-height: 1.65; overflow-wrap: anywhere; }
.comment-body p { margin: 0 0 0.6rem; }
.comment-footer { margin-top: 0.6rem; font-size: 0.75rem; }
.comment-timestamp a { color: #94a3b8; text-decoration: none; }
.comment-timestamp a:hover { color: #4f46e5; }
.comment-form { margin-top: 1.25rem; }
.comment-form h4 { margin-bottom: 0.75rem; }
.comment-form iframe#comment-editor {
    width: 100%;
    min-height: 200px;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
    background: #fff;
}
.comment-thread ol { margin: 0; padding: 0; list-style: none; }
.comment-thread .comment { background: #fff; }
.comment .comment .comment { background: #f8fafc; }
.paging-control-container {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    margin: 1rem 0;
    font-size: 0.85rem;
}
.paging-control-container a { color: #4f46e5; font-weight: 600; text-decoration: none; }
.author-profile {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-top: 1.5rem;
    padding: 1rem;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 1rem;
}
.author-image { width: 56px; height: 56px; border-radius: 999px; object-fit: cover; }
.author-name a { color: #0f172a; font-weight: 700; text-decoration: none; }
.author-desc { color: #64748b; font-size: 0.875rem; }

/* ===== Blog pager ===== */
.blog-pager {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.75rem;
    margin-top: 2rem;
}
.blog-pager a {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    height: 2.6rem;
    padding: 0 1.1rem;
    border: 1px solid #e2e8f0;
    border-radius: 0.85rem;
    background: #fff;
    color: #334155;
    font-size: 0.875rem;
    font-weight: 600;
    text-decoration: none;
}
.blog-pager a:hover { border-color: #c7d2fe; background: #eef2ff; color: #4f46e5; }

b:if.script:
//

function initialize(total) {

    var totalPosts = total;
    var postsPerPage = 6;

    function escapeHtml(str) {
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function plainText(html) {
        var d = document.createElement('div');
        d.innerHTML = html;
        return (d.textContent || d.innerText || '').replace(/\s+/g, ' ').trim();
    }

    function skeletonHtml() {
        var s = '';
        for (var i = 0; i < postsPerPage; i++) {
            s += '<div class="post snip-col-4 flex gap-3 rounded-2xl border border-slate-200 bg-white p-3 shadow-sm sm:block sm:p-5">';
            s += '<div class="h-24 w-24 shrink-0 animate-pulse rounded-xl bg-slate-200 sm:mb-4 sm:h-32 sm:w-full"></div>';
            s += '<div class="flex min-w-0 flex-1 flex-col">';
            s += '<div class="h-3 w-16 animate-pulse rounded-full bg-slate-200 sm:mt-1 sm:w-20"></div>';
            s += '<div class="mt-2 h-4 w-3/4 animate-pulse rounded-lg bg-slate-200 sm:mt-3 sm:h-5"></div>';
            s += '<div class="mt-2 h-3 w-full animate-pulse rounded bg-slate-200"></div>';
            s += '<div class="mt-2 hidden h-3 w-5/6 animate-pulse rounded bg-slate-200 sm:block"></div>';
            s += '</div>';
            s += '</div>';
        }
        return s;
    }

    function fetchPosts(pageNumber, callback) {
        var startIndex = (pageNumber - 1) * postsPerPage;
        var feedUrl = '/feeds/posts/default?alt=json-in-script&start-index=' + (startIndex + 1) + '&max-results=' + postsPerPage;
        $('#post-container').html(skeletonHtml());
        $.ajax({
            url: feedUrl,
            dataType: 'jsonp',
            success: function (data) {
                var posts = data.feed.entry || [];
                callback(posts);
            },
            error: function (jqXHR, textStatus, errorThrown) {
                console.error('Error fetching posts:', textStatus, errorThrown);
                $('#post-container').html('<div class="col-span-full rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-sm text-slate-500">Gagal memuat postingan. Coba lagi nanti.</div>');
            }
        });
    }

    function renderPosts(posts) {
        var html = '';
        $('#post-container').empty();

        if (!posts || posts.length === 0) {
            $('#post-container').html('<div class="col-span-full rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-sm text-slate-500">Belum ada postingan.</div>');
            return;
        }

        posts.forEach(function (post) {
            var title = (post.title && post.title.$t) ? post.title.$t : 'Tanpa Judul';
            var links = post.link || [];
            var alternate = null;
            for (var i = 0; i < links.length; i++) {
                if (links[i].rel === 'alternate') { alternate = links[i]; break; }
            }
            var url = alternate ? alternate.href : '#';
            var raw = (post.content && post.content.$t) ? post.content.$t : ((post.summary && post.summary.$t) ? post.summary.$t : '');
            var text = plainText(raw);
            var snippet = text.length > 180 ? text.substring(0, 180) + '…' : text;

            var dateStr = '';
            if (post.published && post.published.$t) {
                var d = new Date(post.published.$t);
                dateStr = d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
            }

            var thumbHtml;
            if (post.media$thumbnail && post.media$thumbnail.url) {
                var turl = post.media$thumbnail.url.replace(/\/s72(-c)?\//, '/w640-h360-c/');
                thumbHtml = '<a href="' + url + '" class="block h-24 w-24 shrink-0 overflow-hidden rounded-xl bg-slate-100 sm:mb-4 sm:h-auto sm:w-full sm:aspect-video">' +
                    '<img src="' + turl + '" alt="' + escapeHtml(title) + '" loading="lazy" class="h-full w-full object-cover transition duration-300 group-hover:scale-105"/></a>';
            } else {
                thumbHtml = '<div class="flex h-24 w-24 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-indigo-500 via-violet-500 to-fuchsia-500 sm:mb-4 sm:h-auto sm:w-full sm:aspect-video">' +
                    '<i class="material-icons text-3xl text-white/80 sm:text-4xl">auto_stories</i></div>';
            }

            html += '<article class="post snip-col-4 group flex gap-3 rounded-2xl border border-slate-200 bg-white p-3 shadow-sm transition duration-300 hover:-translate-y-1 hover:border-indigo-200 hover:shadow-soft sm:block sm:p-5">';
            html += thumbHtml;
            html += '<div class="flex min-w-0 flex-1 flex-col">';
            if (dateStr) {
                html += '<div class="mb-1 hidden items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-slate-400 sm:mb-2 sm:flex"><i class="material-icons text-sm">schedule</i><span>' + escapeHtml(dateStr) + '</span></div>';
            }
            html += '<h2 class="post-title text-sm font-bold leading-snug text-slate-900 transition group-hover:text-indigo-600 sm:text-lg"><a href="' + url + '">' + escapeHtml(title) + '</a></h2>';
            html += '<p class="post-summary mt-1 line-clamp-2 flex-1 text-xs leading-relaxed text-slate-500 sm:mt-2 sm:line-clamp-none sm:text-sm">' + escapeHtml(snippet) + '</p>';
            html += '<span class="mt-2 hidden items-center gap-1.5 text-sm font-semibold text-indigo-600 sm:mt-4 sm:inline-flex">Baca selengkapnya<i class="material-icons text-base">arrow_forward</i></span>';
            html += '</div>';
            html += '</article>';
        });
        $('#post-container').html(html);
    }

    $(function () {
        if (totalPosts <= 0) {
            $('#post-container').html('<div class="col-span-full rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-sm text-slate-500">Belum ada postingan.</div>');
            return;
        }
        $('#pagination-container').pagination({
            dataSource: function (done) {
                done(new Array(totalPosts));
            },
            pageSize: postsPerPage,
            showPrevious: true,
            showGoInput: true,
            showGoButton: true,
            showNext: true,
            callback: function (data, pagination) {
                fetchPosts(pagination.pageNumber, renderPosts);
            }
        });
    });
}

var totalUrl = '/feeds/posts/default?alt=json-in-script&max-results=0';

$.ajax({
    url: totalUrl,
    dataType: 'jsonp',
    success: function (data) {
        initialize(parseInt(data.feed.openSearch$totalResults.$t, 10));
    },
    error: function (jqXHR, textStatus, errorThrown) {
        console.error('Error fetching total posts:', textStatus, errorThrown);
        $('#post-container').html('<div class="col-span-full rounded-2xl border border-dashed border-slate-300 bg-white p-10 text-center text-sm text-slate-500">Gagal memuat postingan. Coba lagi nanti.</div>');
    }
});
//

body.script:
//
(function () {
    var side = document.getElementById('side');
    var overlay = document.getElementById('sidebar-overlay');
    var toggle = document.getElementById('menu-toggle');
    var closeBtn = document.getElementById('sidebar-close');

    function openSidebar() {
        side.classList.remove('-translate-x-full');
        overlay.classList.remove('hidden');
    }
    function closeSidebar() {
        side.classList.add('-translate-x-full');
        overlay.classList.add('hidden');
    }

    if (toggle) { toggle.addEventListener('click', openSidebar); }
    if (closeBtn) { closeBtn.addEventListener('click', closeSidebar); }
    if (overlay) { overlay.addEventListener('click', closeSidebar); }
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') { closeSidebar(); }
    });

    var path = window.location.pathname.replace(/\/$/, '') || '/';
    Array.prototype.forEach.call(side.querySelectorAll('a[href]'), function (a) {
        var href = (a.getAttribute('href') || '').replace(/\/$/, '') || '/';
        if (href === path) {
            a.classList.add('bg-white/10', 'text-white');
            a.classList.remove('text-indigo-100/70');
            var icon = a.querySelector('.material-icons');
            if (icon) {
                icon.classList.add('text-indigo-300');
                icon.classList.remove('text-indigo-300/80');
            }
        }
        a.addEventListener('click', closeSidebar);
    });
})();
//
